sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

	// Preventing callback loop by detecking update in u_trello_card_id

	if (current.u_trello_card_id.changes())
		return;

    // Prepare data for payload

    var data_u_entity = current.getTableName();
    var data_u_entity_id = current.getUniqueValue();
    var data_u_operation = '';
    var data_u_correlation_id = current.getUniqueValue();
    var data_number = current.getDisplayValue('task');
    var task_id = current.getValue('task');
	var data_u_trello_card_id = current.getValue('u_trello_card_id');

	var data_short_desc = current.task.short_description.getDisplayValue();

	var data_list_before = previous ? previous.getValue('lane'): '';
	var data_list_before_display = previous ? previous.getDisplayValue('lane') : '';
	var data_list_after = current.getValue('lane');
	var data_list_after_display = current.getDisplayValue('lane');
    var data_source_system = "servicenow";

	var operation = current.operation();

    if (operation == 'insert') {
        data_u_operation = 'CARD_CREATE';

    } else if (operation == 'update') {
        if (current.getValue('removed') == 1) {
            data_u_operation = 'CARD_REMOVE';

        } else data_u_operation = 'CARD_UPDATE';
    }

    var payload = {
        "event_type": data_u_operation,
        "entity_id": data_u_entity_id,
        "correlation_id": data_u_correlation_id,
		"source_system": data_source_system,
		"trello_card_id": data_u_trello_card_id,
		"source_url": "https://dev342970.service-now.com",
        "data": {
            "number": data_number,
            "short_description": data_short_desc,
			"listBefore": data_list_before,
			"listBeforeName": data_list_before_display,
			"listAfter": data_list_after,
			"listAfterName": data_list_after_display
        }
    };

    createOutboundEvent('trello', payload);
    createOutboundEvent('mariadb', payload);

    function createOutboundEvent(target, payload) {
        var newCard = new GlideRecord('x_1044869_tomek_0_outbound_event');
        newCard.initialize();
        newCard.u_entity = data_u_entity;
        newCard.u_entity_id = data_u_entity_id;
        newCard.u_correlation_id = data_u_correlation_id;
        newCard.u_payload = JSON.stringify(payload);
        newCard.u_target = target;
        newCard.u_operation = data_u_operation;
		newCard.u_status = 'NEW';
		newCard.u_retry_count = 0;

        newCard.insert();
    }


})(current, previous);
